package auth

// StandardRoleDefinition is a finite, explicit action set. Catalog additions do
// not enter a Role automatically. Customers can copy these into custom Roles.
type StandardRoleDefinition struct {
	Key         string
	Name        string
	Description string
	Permissions []Permission
}

func StandardRoles() []StandardRoleDefinition {
	return []StandardRoleDefinition{
		{Key: "auditor", Name: "Auditor", Description: "Read security audit facts for the assigned organization or environment, without execution content.", Permissions: []Permission{PermissionAuditEventsRead}},
		{Key: "agent_user", Name: "Agent User", Description: "Use assigned Agents in own and authorized shared conversations.", Permissions: []Permission{PermissionAgentsUse}},
		{Key: "agent_administrator", Name: "Agent Administrator", Description: "Read, use, delete and restore assigned Agents and configure their chat connections. Does not grant Session history or deployment changes.", Permissions: []Permission{PermissionAgentsRead, PermissionAgentsUse, PermissionAgentsDelete, PermissionAgentsRestore, PermissionAgentConnectionsRead, PermissionAgentConnectionsCreate, PermissionAgentConnectionsUpdateCredentials, PermissionAgentConnectionsAuthorize, PermissionAgentConnectionsDelete}},
		{Key: "session_viewer", Name: "Session Viewer", Description: "Read all conversations and schedule inputs for assigned Agents, including other people’s personal Sessions.", Permissions: []Permission{PermissionAgentsRead, PermissionSessionsRead, PermissionTriggersRead}},
		{Key: "session_operator", Name: "Session Operator", Description: "Read, stop and continue all Sessions for assigned Agents, including keyed creation.", Permissions: []Permission{PermissionAgentsRead, PermissionAgentsUse, PermissionSessionsRead, PermissionSessionsCreateKeyed, PermissionSessionsSend, PermissionSessionsAnswer, PermissionSessionsResume, PermissionSessionsInterrupt, PermissionSessionsCancel, PermissionSessionsClose, PermissionTriggersRead}},
		{Key: "session_administrator", Name: "Session Administrator", Description: "Operate all Sessions for assigned Agents and reconcile or abandon chat deliveries.", Permissions: []Permission{PermissionAgentsRead, PermissionAgentsUse, PermissionSessionsRead, PermissionSessionsCreateKeyed, PermissionSessionsSend, PermissionSessionsAnswer, PermissionSessionsResume, PermissionSessionsInterrupt, PermissionSessionsCancel, PermissionSessionsClose, PermissionTriggersRead, PermissionSessionsCheckDelivery, PermissionSessionsAbandonDelivery}},
		{Key: "deployment_publisher", Name: "Deployment Publisher", Description: "Register deployments and inspect definitions. Preparation can use configured workload credentials. Does not activate deployments.", Permissions: []Permission{PermissionDeploymentsRead, PermissionDeploymentsPublish, PermissionTemplatesRead, PermissionAgentsRead}},
		{Key: "deployment_administrator", Name: "Deployment Administrator", Description: "Register and activate deployments, inspect Agent definitions and refresh Templates. Can use configured workload credentials.", Permissions: []Permission{PermissionDeploymentsRead, PermissionDeploymentsPublish, PermissionDeploymentsPromote, PermissionTemplatesRead, PermissionTemplatesRefresh, PermissionAgentsRead}},
		{Key: "computer_viewer", Name: "Computer Viewer", Description: "Inspect Computer state and Command status without reading output or executing commands.", Permissions: []Permission{PermissionComputersRead}},
		{Key: "computer_debugger", Name: "Computer Debugger", Description: "Execute and cancel Commands and read their output. Trusted guest and workload-credential access; excludes platform creation, deletion and retention changes.", Permissions: []Permission{PermissionComputersRead, PermissionComputersReadOutput, PermissionComputersExecute, PermissionComputersCancelCommand}},
		{Key: "computer_administrator", Name: "Computer Administrator", Description: "Manage Computers and Commands, including execution, deletion and retention. Browse Template and Secret metadata.", Permissions: []Permission{PermissionComputersRead, PermissionComputersReadOutput, PermissionComputersExecute, PermissionComputersCancelCommand, PermissionComputersCreate, PermissionComputersWake, PermissionComputersHibernate, PermissionComputersUpdateRetention, PermissionComputersDelete, PermissionTemplatesRead, PermissionSecretsRead}},
		{Key: "secret_administrator", Name: "Secret Administrator", Description: "Read Secret metadata, create, rotate and revoke Secrets. Stored values cannot be retrieved.", Permissions: []Permission{PermissionSecretsRead, PermissionSecretsCreate, PermissionSecretsRotate, PermissionSecretsRevoke}},
		{Key: "api_key_administrator", Name: "API Key Administrator", Description: "Create, update, rotate and revoke API keys. Rotation permits acting as those keys. Does not assign Roles.", Permissions: []Permission{PermissionAPIKeysRead, PermissionAPIKeysCreate, PermissionAPIKeysUpdate, PermissionAPIKeysRotate, PermissionAPIKeysRevoke}},
		{Key: "access_viewer", Name: "Access Viewer", Description: "Inspect members, invitations, Groups, Roles and assignments without changing access.", Permissions: []Permission{PermissionMembersRead, PermissionInvitationsRead, PermissionGroupsRead, PermissionRolesRead, PermissionAssignmentsRead}},
		{Key: "access_administrator", Name: "Access Administrator", Description: "Manage organization membership and access. Can delegate powerful workload authority.", Permissions: []Permission{PermissionMembersRead, PermissionMembersRemove, PermissionInvitationsRead, PermissionInvitationsCreate, PermissionInvitationsRevoke, PermissionGroupsRead, PermissionGroupsCreate, PermissionGroupsUpdate, PermissionGroupsDelete, PermissionGroupsAddMember, PermissionGroupsRemoveMember, PermissionRolesRead, PermissionRolesCreate, PermissionRolesUpdate, PermissionRolesDelete, PermissionAssignmentsRead, PermissionAssignmentsCreate, PermissionAssignmentsUpdate, PermissionAssignmentsDelete}},
		{Key: "organization_structure_administrator", Name: "Organization Structure Administrator", Description: "Manage Project and Environment structure and Project history retention across the organization.", Permissions: []Permission{PermissionProjectsRead, PermissionProjectsCreate, PermissionProjectsUpdate, PermissionProjectsUpdateRetention, PermissionEnvironmentsRead, PermissionEnvironmentsCreate, PermissionEnvironmentsUpdate}},
		{Key: "environment_resource_administrator", Name: "Environment Resource Administrator", Description: "Manage environment resources and API keys. Excludes organization settings, membership and access administration.", Permissions: []Permission{PermissionAgentsRead, PermissionAgentsUse, PermissionAgentsDelete, PermissionAgentsRestore, PermissionAgentConnectionsRead, PermissionAgentConnectionsCreate, PermissionAgentConnectionsUpdateCredentials, PermissionAgentConnectionsAuthorize, PermissionAgentConnectionsDelete, PermissionSessionsRead, PermissionSessionsCreateKeyed, PermissionSessionsSend, PermissionSessionsAnswer, PermissionSessionsResume, PermissionSessionsInterrupt, PermissionSessionsCancel, PermissionSessionsClose, PermissionSessionsCheckDelivery, PermissionSessionsAbandonDelivery, PermissionDeploymentsRead, PermissionDeploymentsPublish, PermissionDeploymentsPromote, PermissionTemplatesRead, PermissionTemplatesRefresh, PermissionTriggersRead, PermissionComputersRead, PermissionComputersReadOutput, PermissionComputersExecute, PermissionComputersCancelCommand, PermissionComputersCreate, PermissionComputersWake, PermissionComputersHibernate, PermissionComputersUpdateRetention, PermissionComputersDelete, PermissionSecretsRead, PermissionSecretsCreate, PermissionSecretsRotate, PermissionSecretsRevoke, PermissionAPIKeysRead, PermissionAPIKeysCreate, PermissionAPIKeysUpdate, PermissionAPIKeysRotate, PermissionAPIKeysRevoke}},
	}
}
